    "profile": "https://www.pkuih.edu.cn/department/details_931_9084.html",
    "title": "营养科",
    "intro": [
      "营养科是对各种原因引起的超重、肥胖、消瘦、营养物质摄入不均衡、维生素和微量元素缺乏的患者通过营养素检测、营养评估和临床表现进行营养诊断，并根据患者的饮食习惯、疾病诊断和生化检查确定一对一的饮食方案，并结合医用食品、药品以及维生素和微量元素对患者进行营养治疗的科室。营养科科室梯队配备合理，现有科室人员均为研究生学历，具有良好的营养学专业基础和治疗水平。同时，营养科注重医疗和科研全面发展，承担了多项国家和省部级课题研究，并利用临床医学与营养学相结合的方式和整体观念，多方法、多角度、多层次的为患者提供个性化营养治疗服务。"
    ],
    "id": "_931_9084",
    "features": [
      {
        "tag": "特色诊疗",
        "title": "",
        "desc": "(1）医学营养减重；(2）妊娠期糖尿病的营养治疗；(3）肿瘤营养治疗；(4）慢性肾病患者的营养评估及个性化营养指导；(5）代谢综合征（高血糖、高血脂、高尿酸和高同型半胱氨酸）的营养调理；(6）外科围手术期营养。"
      },
      {
        "tag": "诊疗范围",
        "title": "",
        "desc": "营养科门诊除常规检验检查外，还可进行人体成分分析、血生化、维生素及微量元素等营养相关指标的检测。如果您有以下情况，建议到营养科门诊就诊： (1）肥胖； (2）备孕及孕期营养需求，或患有妊娠期糖尿病。 (3）外科手术前后、肿瘤放化疗期或康复期； (4）患有慢性肾病或正在透析； (5）患有糖尿病、高血压、高血脂、高尿酸等代谢性疾病； (6）消瘦或不明原因体重下降； (7）明显食欲下降，进食量减少甚至不能进食； (8）慢性腹泻、便秘。"
      }
    ],
